<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import type { MovimientoDetalle,MovimientoFiltros,MovimientoFinanciero,MovimientoPayload,OpcionMovimiento } from '../interfaces/movimiento-financiero.interface'
import { cambiarEstadoMovimientoFinanciero,guardarMovimientoFinanciero,listarMovimientosFinancieros,obtenerMovimientoFinanciero,opcionesMovimientoFinanciero } from '../services/movimiento-financiero'
const line=():MovimientoDetalle=>({cuenta_contable_id:0,centro_costo_id:null,analitico:null,naturaleza:'D',importe:0}),blankFilters=():MovimientoFiltros=>({detalle_periodo_id:'',cuenta_contable_id:'',tipo_comprobante_id:'',tipo_documento_id:'',fecha_desde:'',fecha_hasta:''}),blankForm=():MovimientoPayload=>({periodo_financiero_id:0,detalle_periodo_id:0,tipo_comprobante_id:0,numero_comprobante:'',fecha_comprobante:new Date().toISOString().slice(0,10),etiqueta:'',valor_etiqueta:'',cuenta_contable_id:null,numero_cheque:'',modalidad_pago_id:null,fecha_documento:'',tipo_documento_id:null,numero_documento:'',banco_id:null,glosa:'',detalles:[line(),{...line(),naturaleza:'H'}]})
const filters=reactive(blankFilters()),form=reactive(blankForm()),rows=ref<MovimientoFinanciero[]>([]),periods=ref<OpcionMovimiento[]>([]),accounts=ref<OpcionMovimiento[]>([]),types=ref<OpcionMovimiento[]>([]),documents=ref<OpcionMovimiento[]>([]),payments=ref<OpcionMovimiento[]>([]),banks=ref<OpcionMovimiento[]>([]),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),showForm=ref(false),editing=ref<number|null>(null),detail=ref<MovimientoFinanciero|null>(null)
const debit=computed(()=>form.detalles.filter(x=>x.naturaleza==='D').reduce((a,x)=>a+Number(x.importe||0),0)),credit=computed(()=>form.detalles.filter(x=>x.naturaleza==='H').reduce((a,x)=>a+Number(x.importe||0),0)),difference=computed(()=>Number((debit.value-credit.value).toFixed(2))),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2}).format(Number(v||0)),date=(v?:string)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'-'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarMovimientosFinancieros(filters,next);rows.value=r.data;periods.value=r.periodos||periods.value;accounts.value=r.cuentas_contables||accounts.value;types.value=r.tipos_comprobante||types.value;documents.value=r.tipos_documento||documents.value;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function create(){editing.value=null;Object.assign(form,blankForm());const p=periods.value[0];if(p){form.detalle_periodo_id=p.id;form.periodo_financiero_id=p.periodo_financiero_id||0}showForm.value=true}
async function edit(item:MovimientoFinanciero){loading.value=true;try{const x=await obtenerMovimientoFinanciero(item.id);editing.value=x.id;Object.assign(form,blankForm(),x,{fecha_comprobante:x.fecha_comprobante.slice(0,10),fecha_documento:x.fecha_documento?.slice(0,10)||'',detalles:x.detalles.map(y=>({...y,importe:Number(y.importe)}))});showForm.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function view(item:MovimientoFinanciero){loading.value=true;try{detail.value=await obtenerMovimientoFinanciero(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){if(Math.abs(difference.value)>.009){error.value='El movimiento no está cuadrado. El debe y el haber deben coincidir.';return}if(form.detalles.some(x=>!x.cuenta_contable_id||x.importe<=0)){error.value='Complete la cuenta y el importe de todas las líneas.';return}loading.value=true;error.value='';try{await guardarMovimientoFinanciero(editing.value,{...form,detalles:form.detalles.map(x=>({...x}))});success.value=`Movimiento ${editing.value?'actualizado':'registrado'} correctamente.`;showForm.value=false;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(item:MovimientoFinanciero){if(!confirm(`¿Desea ${item.activo?'anular':'activar'} el movimiento ${item.numero_comprobante}?`))return;loading.value=true;try{await cambiarEstadoMovimientoFinanciero(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function addLine(){form.detalles.push(line())}function removeLine(i:number){if(form.detalles.length>2)form.detalles.splice(i,1)}function clear(){Object.assign(filters,blankFilters());load(1)}
onMounted(async()=>{try{const x=await opcionesMovimientoFinanciero();periods.value=x.periodo?[x.periodo]:[];accounts.value=x.cuentas_contables;types.value=x.tipos_comprobante;documents.value=x.tipos_documento;payments.value=x.modalidades_pago;banks.value=x.bancos}catch(e){error.value=message(e)}await load()})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Movimientos financieros</nav><header class="hero"><div class="mark">MF</div><div><small>MIA · FINANZAS · MOVIMIENTOS</small><h1>Movimientos financieros</h1><p>Comprobantes, pagos y asientos vinculados a tesorería.</p></div><strong>{{total}} movimientos</strong><button @click="create">+ Nuevo movimiento</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="filters.detalle_periodo_id"><option value="">Todos los periodos</option><option v-for="x in periods" :key="x.id" :value="x.id">{{x.anio}}-{{String(x.mes||'').padStart(2,'0')}}</option></select><select v-model="filters.cuenta_contable_id"><option value="">Todas las cuentas</option><option v-for="x in accounts" :key="x.id" :value="x.id">{{x.cta_contable}} · {{x.descripcion}}</option></select><select v-model="filters.tipo_comprobante_id"><option value="">Todos los comprobantes</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.detalle}}</option></select><select v-model="filters.tipo_documento_id"><option value="">Todos los documentos</option><option v-for="x in documents" :key="x.id" :value="x.id">{{x.nombre}}</option></select><input v-model="filters.fecha_desde" type="date"><input v-model="filters.fecha_hasta" type="date"><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron movimientos.</div><div v-else class="scroll"><table><thead><tr><th>Comprobante</th><th>Fecha</th><th>Glosa</th><th>Cuenta de tesorería</th><th>Documento</th><th>Modalidad / banco</th><th>Importe</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.numero_comprobante}}</b><small>{{item.tipo_comprobante?.detalle}}</small></td><td>{{date(item.fecha_comprobante)}}</td><td>{{item.glosa}}<small>{{item.valor_etiqueta}}</small></td><td>{{item.cuenta_contable?.cta_contable}}<small>{{item.cuenta_contable?.descripcion}}</small></td><td>{{item.tipo_documento?.nombre}} {{item.numero_documento}}</td><td>{{item.modalidad_pago?.detalle}}<small>{{item.banco?.descripcion}}</small></td><td class="number"><b>{{money(item.detalles?.filter(x=>x.naturaleza==='D').reduce((a,x)=>a+Number(x.importe),0)||0)}}</b></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'ANULADO'}}</span></td><td class="actions"><button @click="view(item)">Ver</button><button v-if="item.activo" class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Anular':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog form" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO MOVIMIENTO'}}</small><h2>{{editing?'Editar':'Registrar'}} movimiento financiero</h2></div><button type="button" @click="showForm=false">×</button></header><div class="grid"><label>Tipo de comprobante<select v-model.number="form.tipo_comprobante_id" required><option :value="0">Seleccione</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.detalle}}</option></select></label><label>Número<input v-model.trim="form.numero_comprobante" required></label><label>Fecha<input v-model="form.fecha_comprobante" type="date" required></label><label>Cuenta de tesorería<select v-model.number="form.cuenta_contable_id"><option :value="null">Seleccione</option><option v-for="x in accounts" :key="x.id" :value="x.id">{{x.cta_contable}} · {{x.descripcion}}</option></select></label><label>Modalidad de pago<select v-model.number="form.modalidad_pago_id"><option :value="null">Seleccione</option><option v-for="x in payments" :key="x.id" :value="x.id">{{x.detalle}}</option></select></label><label>Banco<select v-model.number="form.banco_id"><option :value="null">Seleccione</option><option v-for="x in banks" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Tipo documento<select v-model.number="form.tipo_documento_id"><option :value="null">Seleccione</option><option v-for="x in documents" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Número documento<input v-model.trim="form.numero_documento"></label><label>Número cheque<input v-model.trim="form.numero_cheque"></label><label class="span3">Glosa<textarea v-model.trim="form.glosa" maxlength="500" required></textarea></label></div><div class="lines-head"><h3>Detalle contable</h3><button type="button" @click="addLine">+ Agregar línea</button></div><div class="scroll"><table class="lines"><thead><tr><th>Cuenta contable</th><th>Naturaleza</th><th>Importe</th><th></th></tr></thead><tbody><tr v-for="(item,index) in form.detalles" :key="index"><td><select v-model.number="item.cuenta_contable_id" required><option :value="0">Seleccione</option><option v-for="x in accounts" :key="x.id" :value="x.id">{{x.cta_contable}} · {{x.descripcion}}</option></select></td><td><select v-model="item.naturaleza"><option value="D">DEBE</option><option value="H">HABER</option></select></td><td><input v-model.number="item.importe" type="number" min=".01" step=".01" required></td><td><button type="button" class="danger" @click="removeLine(index)">×</button></td></tr></tbody></table></div><div class="balance"><div>DEBE <b>{{money(debit)}}</b></div><div>HABER <b>{{money(credit)}}</b></div><div :class="difference?'unbalanced':'balanced'">DIFERENCIA <b>{{money(difference)}}</b></div></div><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading||!!difference">Guardar movimiento</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>MOVIMIENTO #{{detail.id}}</small><h2>{{detail.tipo_comprobante?.detalle}} · {{detail.numero_comprobante}}</h2></div><span :class="detail.activo?'good':'bad'">{{detail.activo?'ACTIVO':'ANULADO'}}</span><button @click="detail=null">×</button></header><div class="facts"><div><small>FECHA</small><b>{{date(detail.fecha_comprobante)}}</b></div><div><small>DOCUMENTO</small><b>{{detail.tipo_documento?.nombre}} {{detail.numero_documento}}</b></div><div><small>BENEFICIARIO</small><b>{{detail.valor_etiqueta||'-'}}</b></div></div><p>{{detail.glosa}}</p><div class="scroll"><table><thead><tr><th>Cuenta</th><th>Centro de costo</th><th>Debe</th><th>Haber</th></tr></thead><tbody><tr v-for="(x,i) in detail.detalles" :key="x.id||i"><td><b>{{x.cuenta_contable?.cta_contable}}</b><small>{{x.cuenta_contable?.descripcion}}</small></td><td>{{x.centro_costo?.nombre||'-'}}</td><td class="number">{{x.naturaleza==='D'?money(x.importe):'-'}}</td><td class="number">{{x.naturaleza==='H'?money(x.importe):'-'}}</td></tr></tbody></table></div></section></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small,.facts small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:repeat(4,1fr) 125px 125px auto auto;gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog select,.dialog textarea{box-sizing:border-box;width:100%;padding:8px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.49rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1200px;border-collapse:collapse;font-size:.48rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.number{text-align:right}.good,.bad{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.44rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.actions{display:flex;gap:4px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:55px;text-align:center}.card>footer,.dialog>footer{padding:12px;display:flex;justify-content:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:15px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(950px,100%);max-height:94vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;gap:10px}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.grid label{display:grid;gap:4px;color:#5d7078;font-size:.49rem;font-weight:700}.span3{grid-column:span 3}.dialog textarea{min-height:50px}.lines-head{display:flex;align-items:center;margin-top:12px}.lines-head h3{flex:1;font-size:.65rem}.lines{min-width:700px}.lines td{padding:5px}.balance{display:flex;justify-content:flex-end;gap:8px;margin-top:10px}.balance div{display:grid;gap:3px;min-width:110px;padding:9px;background:#edf3f5;font-size:.48rem}.balanced{color:#267153!important;background:#e5f7ec!important}.unbalanced{color:#9d414a!important;background:#fdebed!important}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.facts div{display:grid;gap:4px;padding:10px;background:#f1f6f7}.dialog>p{font-size:.54rem}@media(max-width:900px){.filters,.grid{grid-template-columns:repeat(2,1fr)}.span3{grid-column:span 2}}@media(max-width:600px){.filters,.grid,.facts{grid-template-columns:1fr}.span3{grid-column:auto}.hero{flex-wrap:wrap}.hero .mark{display:none}.balance{display:grid}}
</style>
